import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var i=JSON.parse(`{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"users/notifications.md","filePath":"users/notifications.md","lastUpdated":1781102819000}`),a={name:`users/notifications.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /users/notifications.md for this page in Markdown format</div><h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to “Notifications”">​</a></h1><p>SysReptor provides a notification system to keep you informed about important events related to your projects and findings. In-app notifications are displayed in the menu bar of the web interface.</p><p><img src="/images/notifications.png" alt="" width="567" height="304"></p><p>The menu bar shows only unread notifications. A full list (including already read) notifications is available in your user profile. Click the bell icon to temporarily hide notifications for uninterrupted work.</p><h2 id="notification-triggers" tabindex="-1">Notification Triggers <a class="header-anchor" href="#notification-triggers" aria-label="Permalink to “Notification Triggers”">​</a></h2><p>Notifications are created for following events:</p><ul><li>Added as a member to a project</li><li>Assigned a finding, section, or note</li><li>Commented on a finding/section assigned to you</li><li>Mentioned in a comment via <code>@username</code></li><li>New replies in comment threads you are part of (created by you or mentioned)</li><li>Project finished where you are a member</li><li>Project deleted where you are a member</li><li>Project archived where you are a member</li><li>No backup created for more than 30 days</li><li>Remote notification e.g. SysReptor update available</li><li>Custom notifications created by superusers</li></ul><h2 id="custom-notifications" tabindex="-1">Custom Notifications <a class="header-anchor" href="#custom-notifications" aria-label="Permalink to “Custom Notifications”">​</a></h2><p>Superusers can create custom notifications through the Django admin interface at <code>/admin/notifications/customnotificationspec/</code> to inform users about announcements, maintenance windows, design changes, or other information.</p><p><strong>Fields:</strong></p><ul><li><strong>Title</strong> (required): Notification title displayed to users</li><li><strong>Text</strong> (required): Main notification message body</li><li><strong>Link URL</strong> (optional): URL for more information or action</li><li><strong>Active Until</strong> (optional): Date when notification automatically expires</li><li><strong>Visible For Days</strong> (optional): Number of days notification remains visible per user. New users receive the notification with visibility starting from their creation date.</li><li><strong>User Conditions</strong> (optional): JSON filter for targeting specific users, e.g. <code>{&quot;is_superuser&quot;: true}</code> or <code>{&quot;is_designer&quot;: false}</code>. Leave empty to target all users.</li></ul><p>When both <code>active_until</code> and <code>visible_for_days</code> are set, the notification expires at whichever date comes first.</p>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};